<template>
  <q-page>
    <div v-if="!ready">
      <h2 class="row items-center q-mb-lg">
        <q-skeleton type="QChip" width="90px" height="50px" class="q-mr-md" />
        <q-skeleton type="text" width="420px" height="60px" />
      </h2>
      <editor-skeleton />
    </div>
    <div v-else>
      <h2 class="row items-center q-gutter-x-lg q-mb-lg">
        <div>{{ readOnly ? "Control" : control.control_id && !$route.query.clone ? "Edit control" : "New control" }}</div>
        <div class="row items-center no-wrap text-grey-7 page-subject">
          <q-chip size="lg" :title="controlType(control.control_type).label">
            <q-avatar :icon="controlType(control.control_type).icon" :color="controlType(control.control_type).color" text-color="white" class="type-avatar" />
            {{ control.control_type }}
          </q-chip>
          <span class="q-ml-xs">{{ control.control_name }}</span>
        </div>
        <q-space />
        <template v-if="control.control_id && $can('runs', 'operate')">
          <run-control-dialog v-if="!dirty" :control_name="control.control_name" :hook="runStarted">
            <q-btn unelevated color="primary" icon="fas fa-play" label="Run" />
          </run-control-dialog>
          <span v-else>
            <q-btn unelevated color="primary" icon="fas fa-play" label="Run" disable />
            <q-tooltip anchor="bottom right" self="top right" :offset="[0, 5]">Apply your changes first: a run uses the saved configuration</q-tooltip>
          </span>
        </template>
      </h2>

      <q-card>
        <q-tabs
          v-model="tab"
          class="text-white bg-blue-grey-7"
          active-color="light-blue-1"
          indicator-color="light-blue-1"
          align="left"
          inline-label
          narrow-indicator
          no-caps>
          <q-tab name="main" label="Main" icon="fas fa-window-maximize" />
          <q-tab name="data" label="Data and logic" icon="fas fa-database" />
          <q-tab name="sql" label="SQL Scripts" icon="fas fa-code" />
          <q-tab v-if="control.control_type !== 'REP' && control.control_type !== 'REC'" name="case" label="Case definition" icon="fas fa-tag" />
          <q-tab name="scheduler" label="Scheduler" icon="fas fa-clock" />
          <q-tab v-if="kpiAvailable && $can('kpis')" name="kpi" label="KPIs" icon="fas fa-calculator" :alert="kpiRenameShown ? 'blue' : false" />
          <q-tab v-if="emailEnabled" name="email" label="Email" icon="fas fa-envelope" />
          <q-tab v-if="control.control_id && $can('runs')" name="log" label="Run log" icon="fas fa-file-medical-alt" />
        </q-tabs>

        <q-separator />

        <q-form v-readonly-guard @submit="persist('stay')" @reset="cancel" :class="{ 'editor-readonly': readOnly }">
          <q-banner v-if="readOnly" dense class="bg-blue-grey-1 text-blue-grey-10">
            <template #avatar><q-icon name="fas fa-eye" size="16px" /></template>
            Read only: your token can view controls but not change them.
          </q-banner>
          <!-- A control not saved yet: what Save still needs, each a link to its tab. -->
          <div v-if="newChecklist" class="row items-center q-gutter-x-sm q-px-lg q-py-xs bg-blue-grey-1 text-blue-grey-9 new-checklist">
            <span class="text-weight-medium">To save:</span>
            <span
              v-for="item in newChecklist"
              :key="item.label"
              class="cursor-pointer"
              :class="item.done ? 'text-positive' : 'text-orange-10'"
              v-keyboard:button
              :aria-label="`${item.label}: ${item.done ? 'done' : 'missing'}, open its tab`"
              @click="tab = item.tab">
              <q-icon :name="item.done ? 'fas fa-check' : 'fas fa-times'" size="11px" class="q-mr-xs" />{{ item.label }}
            </span>
          </div>
          <q-tab-panels v-model="tab" animated keep-alive>
            <q-tab-panel name="main">
              <!-- Three boxes, as the datasource editor's Main tab; what a field does is its hint, always shown. -->
              <div class="q-ma-lg q-gutter-y-md">
                <q-card class="q-pa-sm" flat bordered>
                  <q-item-section class="q-ma-xs">
                    <q-item-label class="text-weight-medium">General</q-item-label>
                  </q-item-section>
                  <q-card-section class="q-pt-sm">
                    <div class="row q-col-gutter-md">
                      <q-input
                        class="col-12 col-sm-6 col-md"
                        outlined
                        v-model="control.control_name"
                        label="Control name *"
                        maxlength="45"
                        hint="Upper case; names the result tables"
                        @update:model-value="(value) => (control.control_name = value ? String(value).toUpperCase() : value)" />

                      <q-input class="col-12 col-sm-6 col-md" outlined v-model="control.control_alias" label="Control alias" />

                  <q-select
                    class="col-12 col-sm-6 col-md"
                    outlined
                    label="Control group"
                    :model-value="control.control_group"
                    use-input
                    hide-selected
                    fill-input
                    clearable
                    input-debounce="0"
                    maxlength="90"
                    :options="controlGroupOptions"
                    @filter="filterControlGroups"
                    @input-value="(value) => (control.control_group = value)"
                    @update:model-value="(value) => (control.control_group = normalizeControlGroup(value))"
                    @blur="control.control_group = normalizeControlGroup(control.control_group)" />

                  <q-select
                    v-if="control.control_id"
                    class="col-12 col-sm-6 col-md-3"
                    outlined
                    v-model="controlVersion"
                    label="Version"
                    :options="controlVersions"
                    @update:model-value="controlVersionChanged">
                    <template v-slot:prepend>
                      <q-icon
                        name="fas fa-tag"
                        size="sm"
                        v-keyboard:button
                        aria-label="Manage versions"
                        @click="$refs.versionsDialog.open()"
                        @click.stop.prevent
                        class="cursor-pointer editor-panel-open"
                        :class="{ 'text-deep-orange-4': versionChanges.length }">
                        <q-badge rounded size="xs" v-if="versionChanges.length" color="green" floating>{{ versionChanges.length }}</q-badge>
                        <q-tooltip anchor="top left" self="bottom left" :offset="[0, 5]">Manage versions</q-tooltip>
                      </q-icon>
                    </template>
                    <template v-slot:no-option>
                      <q-item>
                        <q-item-section class="text-grey"> No past versions </q-item-section>
                      </q-item>
                    </template>
                  </q-select>
                    </div>
                    <q-input class="q-mt-md" v-model="control.control_description" label="Control description" maxlength="500" outlined autogrow />
                  </q-card-section>
                </q-card>

                <q-card class="q-pa-sm" flat bordered>
                  <q-item-section class="q-ma-xs">
                    <q-item-label class="text-weight-medium">Execution</q-item-label>
                  </q-item-section>
                  <q-card-section class="q-pt-sm">
                    <div class="row q-col-gutter-md">
                      <q-select
                        class="col-12 col-sm-6 col-md"
                        outlined
                        emit-value
                        map-options
                        :model-value="control.control_type"
                        :options="controlTypeOptions"
                        label="Control type"
                        @update:model-value="requestTypeChange" />

                      <q-select
                        class="col-12 col-sm-6 col-md"
                        outlined
                        :readonly="control.control_type !== 'REC'"
                        emit-value
                        map-options
                        v-model="control.control_engine"
                        :options="controlEngineOptions"
                        label="Control engine"
                        :hint="control.control_type === 'REC' ? 'Same results either way' : 'Database SQL for this type'" />

                      <q-input
                        class="col-12 col-sm-4 col-md-2"
                        v-model.number="control.parallelism"
                        type="number"
                        outlined
                        label="Parallelism"
                        :min="1"
                        :step="1"
                        hint="PARALLEL hint, up to 4" />

                      <q-input
                        class="col-12 col-sm-4 col-md-2"
                        v-model.number="control.instance_limit"
                        type="number"
                        :min="1"
                        :step="1"
                        outlined
                        label="Instance limit *"
                        hint="Runs at once" />

                      <q-input class="col-12 col-sm-4 col-md-2" v-model.number="control.timeout" type="number" outlined label="Timeout (seconds)" hint="Empty: no timeout" />
                    </div>
                  </q-card-section>
                </q-card>

                <q-card class="q-pa-sm" flat bordered>
                  <q-item-section class="q-ma-xs">
                    <q-item-label class="text-weight-medium">Hooks and results</q-item-label>
                  </q-item-section>
                  <q-card-section class="q-pt-sm">
                    <div class="row q-col-gutter-md">
                      <q-select
                        class="col-12 col-sm-6 col-md"
                        outlined
                        emit-value
                        map-options
                        v-model="control.need_prerun_hook"
                        :options="yesNoOptions"
                        label="Pre-run hook"
                        hint="Called before the run"
                        title="Calls RAPO_PRERUN_CONTROL_HOOK (in_process_id) before the run" />

                      <q-select
                        class="col-12 col-sm-6 col-md"
                        outlined
                        emit-value
                        map-options
                        v-model="control.need_postrun_hook"
                        :options="yesNoOptions"
                        label="Post-run hook"
                        title="Calls RAPO_POSTRUN_CONTROL_HOOK after the run; the KPIs are calculated by it"
                        hint="KPIs need it" />

                      <q-select
                        v-if="emailSupported"
                        class="col-12 col-sm-6 col-md"
                        outlined
                        emit-value
                        map-options
                        v-model="sendEmail"
                        :options="yesNoOptions"
                        label="Send email"
                        hint="Set up in the Email tab" />

                      <q-select
                        class="col-12 col-sm-6 col-md"
                        outlined
                        emit-value
                        map-options
                        v-model="withDeletionDrop"
                        :options="[
                          { label: 'Yes', value: 'N' },
                          { label: 'No, delete on each run', value: 'deletion' },
                          { label: 'No, drop on each run', value: 'drop' },
                        ]"
                        label="Keep past results"
                        hint="Else emptied on each run"
                        @update:model-value="deletionDropChanged" />

                      <q-input
                        v-if="withDeletionDrop === 'N'"
                        class="col-12 col-sm-6 col-md-2"
                        v-model.number="control.days_retention"
                        type="number"
                        outlined
                        label="Retention (days) *"
                        hint="Days results are kept" />
                    </div>
                  </q-card-section>
                </q-card>
              </div>
            </q-tab-panel>

            <q-tab-panel name="data">
              <div class="q-ma-lg q-gutter-y-md">
                <div class="row q-gutter-md" v-if="control.control_type === 'ANL' || control.control_type === 'REP'">
                  <q-select
                    class="col"
                    outlined
                    v-model="control.source_name"
                    use-input
                    hide-selected
                    fill-input
                    input-debounce="0"
                    label="Datasource"
                    :options="datasourceListOptions"
                    @filter="filterDatasourceList">
                    <template v-slot:prepend>
                      <q-icon name="fas fa-table" @click.stop.prevent />
                    </template>
                    <template v-if="canEditView(control.source_name)" v-slot:append>
                      <q-btn aria-label="Edit view SQL" flat round dense size="sm" icon="fas fa-pen" @click.stop.prevent="openViewEditor(control.source_name)">
                        <q-tooltip>Edit the SQL of view {{ control.source_name }}</q-tooltip>
                      </q-btn>
                    </template>
                    <template v-slot:no-option>
                      <q-item>
                        <q-item-section class="text-grey"> No datasources found </q-item-section>
                      </q-item>
                    </template>
                  </q-select>

                  <q-select
                    v-if="control.control_type === 'ANL' || control.control_type === 'REP'"
                    class="col-2"
                    outlined
                    v-model="control.source_date_field"
                    label="Date column"
                    :options="datasourceDateColumns"
                    clearable
                    behavior="menu">
                    <template v-slot:prepend>
                      <q-icon name="far fa-calendar-alt" @click.stop.prevent />
                    </template>
                  </q-select>

                  <q-select
                    class="col-2"
                    outlined
                    label="System"
                    :model-value="control.source_type_a"
                    use-input
                    hide-selected
                    fill-input
                    clearable
                    input-debounce="0"
                    maxlength="90"
                    :options="systemOptions"
                    @filter="filterSystems"
                    @input-value="(value) => (control.source_type_a = value)"
                    @update:model-value="(value) => (control.source_type_a = normalizeSystem(value))"
                    @blur="control.source_type_a = normalizeSystem(control.source_type_a)" />
                </div>

                <div class="row q-gutter-md" v-if="control.control_type === 'REC' || control.control_type === 'CMP'">
                  <q-select
                    class="col"
                    outlined
                    v-model="control.source_name_a"
                    use-input
                    hide-selected
                    fill-input
                    input-debounce="0"
                    label="Datasource A"
                    :options="datasourceListOptions"
                    @filter="filterDatasourceList">
                    <template v-slot:prepend>
                      <q-icon name="fas fa-table" @click.stop.prevent />
                    </template>
                    <template v-if="canEditView(control.source_name_a)" v-slot:append>
                      <q-btn aria-label="Edit view SQL" flat round dense size="sm" icon="fas fa-pen" @click.stop.prevent="openViewEditor(control.source_name_a)">
                        <q-tooltip>Edit the SQL of view {{ control.source_name_a }}</q-tooltip>
                      </q-btn>
                    </template>
                    <template v-slot:no-option>
                      <q-item>
                        <q-item-section class="text-grey"> No datasources found </q-item-section>
                      </q-item>
                    </template>
                  </q-select>

                  <q-select
                    v-if="control.control_type === 'REC'"
                    class="col-1"
                    outlined
                    v-model="control.source_key_field_a"
                    input-debounce="0"
                    label="Key field A"
                    :options="[...new Set([...(datasourceAColumns ? datasourceAColumns : []), 'TAG'])]">
                  </q-select>

                  <q-select
                    v-if="control.control_type === 'CMP'"
                    class="col-2"
                    outlined
                    clearable
                    v-model="control.source_date_field_a"
                    label="Date column A"
                    :options="datasourceADateColumns"
                    behavior="menu">
                    <template v-slot:prepend>
                      <q-icon name="far fa-calendar-alt" @click.stop.prevent />
                    </template>
                  </q-select>

                  <q-select
                    class="col-2"
                    outlined
                    label="System A"
                    :model-value="control.source_type_a"
                    use-input
                    hide-selected
                    fill-input
                    clearable
                    input-debounce="0"
                    maxlength="90"
                    :options="systemOptions"
                    @filter="filterSystems"
                    @input-value="(value) => (control.source_type_a = value)"
                    @update:model-value="(value) => (control.source_type_a = normalizeSystem(value))"
                    @blur="control.source_type_a = normalizeSystem(control.source_type_a)" />

                  <q-select
                    class="col"
                    outlined
                    v-model="control.source_name_b"
                    use-input
                    hide-selected
                    fill-input
                    input-debounce="0"
                    label="Datasource B"
                    :options="datasourceListOptions"
                    @filter="filterDatasourceList">
                    <template v-slot:prepend>
                      <q-icon name="fas fa-table" @click.stop.prevent />
                    </template>
                    <template v-if="canEditView(control.source_name_b)" v-slot:append>
                      <q-btn aria-label="Edit view SQL" flat round dense size="sm" icon="fas fa-pen" @click.stop.prevent="openViewEditor(control.source_name_b)">
                        <q-tooltip>Edit the SQL of view {{ control.source_name_b }}</q-tooltip>
                      </q-btn>
                    </template>
                    <template v-slot:no-option>
                      <q-item>
                        <q-item-section class="text-grey"> No datasources found </q-item-section>
                      </q-item>
                    </template>
                  </q-select>

                  <q-select
                    v-if="control.control_type === 'REC'"
                    class="col-1"
                    outlined
                    v-model="control.source_key_field_b"
                    input-debounce="0"
                    label="Key field B"
                    :options="[...new Set([...(datasourceBColumns ? datasourceBColumns : []), 'TAG'])]">
                  </q-select>

                  <q-select
                    v-if="control.control_type === 'CMP'"
                    class="col-2"
                    outlined
                    clearable
                    v-model="control.source_date_field_b"
                    label="Date column B"
                    :options="datasourceBDateColumns"
                    behavior="menu">
                    <template v-slot:prepend>
                      <q-icon name="far fa-calendar-alt" @click.stop.prevent />
                    </template>
                  </q-select>

                  <q-select
                    class="col-2"
                    outlined
                    label="System B"
                    :model-value="control.source_type_b"
                    use-input
                    hide-selected
                    fill-input
                    clearable
                    input-debounce="0"
                    maxlength="90"
                    :options="systemOptions"
                    @filter="filterSystems"
                    @input-value="(value) => (control.source_type_b = value)"
                    @update:model-value="(value) => (control.source_type_b = normalizeSystem(value))"
                    @blur="control.source_type_b = normalizeSystem(control.source_type_b)" />
                </div>

                <div v-if="chainNote" class="text-caption text-grey-8">
                  <q-icon name="fas fa-link" class="q-mr-xs" />{{ chainNote }}
                </div>

                <div class="row q-gutter-md">
                  <q-select
                    v-if="control.control_type === 'ANL' || control.control_type === 'REP'"
                    class="col"
                    outlined
                    clearable
                    v-model="control.output_table_columns"
                    multiple
                    :options="datasourceColumns"
                    use-chips
                    stack-label
                    label="Select output (leave empty for all columns)">
                    <template v-slot:prepend>
                      <q-icon name="fas fa-columns" class="cursor-pointer" v-keyboard:button aria-label="Get all columns" @click.stop.prevent="populateColumns()">
                        <q-tooltip anchor="top left" self="bottom left" :offset="[0, 5]"> Get all columns </q-tooltip>
                      </q-icon>
                    </template>
                  </q-select>

                  <q-input
                    v-if="control.control_type === 'ANL' || control.control_type === 'REP'"
                    class="col-2"
                    v-model.number="control.output_limit"
                    type="number"
                    outlined
                    label="Output limit">
                    <template v-slot:prepend>
                      <q-icon name="fas fa-list-ol" @click.stop.prevent />
                    </template>
                    <q-tooltip anchor="top left" self="bottom left" :offset="[0, 5]">
                      Limit the number of records in the output table. <br />Leave empty or 0 for no limit.
                    </q-tooltip>
                  </q-input>

                  <div v-if="control.control_type === 'CMP'" class="col">
                    <comparison-output-table-box
                      class="col"
                      v-model="cmpOutputTable"
                      :datasource-a-columns="datasourceAColumns"
                      :datasource-b-columns="datasourceBColumns">
                    </comparison-output-table-box>
                  </div>

                  <q-input
                    v-if="control.control_type === 'CMP'"
                    class="col-2"
                    v-model.number="control.output_limit"
                    type="number"
                    outlined
                    label="Output limit">
                    <template v-slot:prepend>
                      <q-icon name="fas fa-list-ol" @click.stop.prevent />
                    </template>
                    <q-tooltip anchor="top left" self="bottom left" :offset="[0, 5]">
                      Limit the number of records in the output table. <br />Leave empty or 0 for no limit.
                    </q-tooltip>
                  </q-input>

                  <q-select
                    v-if="control.control_type === 'REC'"
                    class="col"
                    outlined
                    clearable
                    v-model="control.output_table_a_columns"
                    multiple
                    :options="datasourceAColumns"
                    use-chips
                    stack-label
                    label="Select output A-side (leave empty for all columns)">
                    <template v-slot:prepend>
                      <q-icon name="fas fa-columns" class="cursor-pointer" v-keyboard:button aria-label="Get all columns" @click.stop.prevent="populateColumns('A')">
                        <q-tooltip anchor="top left" self="bottom left" :offset="[0, 5]"> Get all columns </q-tooltip>
                      </q-icon>
                    </template>
                  </q-select>

                  <q-select
                    v-if="control.control_type === 'REC'"
                    class="col"
                    outlined
                    clearable
                    v-model="control.output_table_b_columns"
                    multiple
                    :options="datasourceBColumns"
                    use-chips
                    stack-label
                    label="Select output B-side (leave empty for all columns)">
                    <template v-slot:prepend>
                      <q-icon name="fas fa-columns" class="cursor-pointer" v-keyboard:button aria-label="Get all columns" @click.stop.prevent="populateColumns('B')">
                        <q-tooltip anchor="top left" self="bottom left" :offset="[0, 5]"> Get all columns </q-tooltip>
                      </q-icon>
                    </template>
                  </q-select>
                </div>

                <div class="row q-my-sm q-gutter-md">
                  <div class="col" v-if="control.control_type === 'ANL' || control.control_type === 'REP'">
                    <code-box
                      label="Filter"
                      v-model="control.source_filter"
                      :columns="datasourceColumns"
                      :template-vars="true"
                      :hide-chips="filterHiddenChips"
                      :examples="codeExamples.filter"
                      :check="checker('filter', 'source_name')">
                    </code-box>
                  </div>
                  <div class="col" v-if="control.control_type === 'REC' || control.control_type === 'CMP'">
                    <code-box
                      label="Filter (Datasource A)"
                      v-model="control.source_filter_a"
                      :columns="datasourceAColumns"
                      :template-vars="true"
                      :hide-chips="filterHiddenChips"
                      :examples="codeExamples.filter"
                      :check="checker('filter', 'source_name_a')">
                    </code-box>
                  </div>
                  <div class="col" v-if="control.control_type === 'REC' || control.control_type === 'CMP'">
                    <code-box
                      label="Filter (Datasource B)"
                      v-model="control.source_filter_b"
                      :columns="datasourceBColumns"
                      :template-vars="true"
                      :hide-chips="filterHiddenChips"
                      :examples="codeExamples.filter"
                      :check="checker('filter', 'source_name_b')">
                    </code-box>
                  </div>
                </div>

                <div class="row q-my-xs q-gutter-md" v-if="control.control_type == 'ANL'">
                  <div class="col">
                    <code-box
                      label="Mismatch criteria (Error definition)"
                      v-model="control.error_definition"
                      :columns="datasourceColumns"
                      :template-vars="true"
                      :examples="codeExamples.error_definition"
                      :check="checker('error_sql', 'source_name')">
                    </code-box>
                  </div>
                </div>

                <div class="col q-my-lg q-gutter-y-md" v-if="control.control_type == 'CMP'">
                  <comparison-criteria-box
                    class="col"
                    title="Match criteria"
                    v-model="ruleConfigObject"
                    :datasource-a-columns="datasourceAColumns"
                    :datasource-b-columns="datasourceBColumns" />

                  <comparison-criteria-box
                    class="col"
                    title="Mismatch criteria"
                    icon="fas fa-not-equal"
                    v-model="ruleErrorObject"
                    :datasource-a-columns="datasourceAColumns"
                    :datasource-b-columns="datasourceBColumns" />
                </div>

                <div class="col q-my-lg q-gutter-y-md" v-if="control.control_type === 'REC'">
                  <q-card class="q-pa-sm" flat bordered>
                    <q-item-section class="q-ma-xs">
                      <q-item-label>Time dimension</q-item-label>
                    </q-item-section>

                    <q-card-section class="q-gutter-xs">
                      <div class="row q-gutter-xs items-center">
                        <q-select
                          class="col-2"
                          outlined
                          v-model="control.source_date_field_a"
                          label="Date column A"
                          :options="datasourceADateColumns"
                          behavior="menu">
                          <template v-slot:prepend>
                            <q-icon name="far fa-calendar-alt" @click.stop.prevent />
                          </template>
                        </q-select>

                        <q-icon class="q-py-md" name="fas fa-equals" size="20px" color="blue-grey-3" />

                        <q-select
                          class="col-2"
                          outlined
                          v-model="control.source_date_field_b"
                          label="Date column B"
                          :options="datasourceBDateColumns"
                          behavior="menu">
                          <template v-slot:prepend>
                            <q-icon name="far fa-calendar-alt" @click.stop.prevent />
                          </template>
                        </q-select>

                        <q-icon
                          v-if="control.source_date_field_a && control.source_date_field_b"
                          class="q-py-md"
                          name="fas fa-circle"
                          size="15px"
                          color="blue-grey-3" />

                        <q-input
                          v-if="control.source_date_field_a && control.source_date_field_b"
                          outlined
                          class="col"
                          v-model.number="ruleConfigObject.time_tolerance_from"
                          type="number"
                          label="Time tolerance from"
                          @update:model-value="ReconciliationTimeFromToleranceChanged">
                          <template v-slot:prepend>
                            <q-icon name="fas fa-long-arrow-alt-left" @click.stop.prevent />
                          </template>
                          <q-tooltip anchor="top left" self="bottom left" :offset="[0, 5]">
                            Lower timestamp tolerance value in seconds (match if A minus B timestamp is greater than this value in seconds)
                          </q-tooltip>
                        </q-input>

                        <q-input
                          v-if="control.source_date_field_a && control.source_date_field_b"
                          outlined
                          class="col"
                          v-model.number="ruleConfigObject.time_tolerance_to"
                          type="number"
                          label="Time tolerance to"
                          @update:model-value="ReconciliationTimeToToleranceChanged">
                          <template v-slot:prepend>
                            <q-icon name="fas fa-long-arrow-alt-right" @click.stop.prevent />
                          </template>
                          <q-tooltip anchor="top left" self="bottom left" :offset="[0, 5]">
                            Upper timestamp tolerance value in seconds (match if A minus B timestamp is lower than this value in seconds)
                          </q-tooltip>
                        </q-input>

                        <q-icon
                          v-if="control.source_date_field_a && control.source_date_field_b"
                          class="q-py-md"
                          name="fas fa-circle"
                          size="15px"
                          color="blue-grey-3" />

                        <q-input
                          v-if="control.source_date_field_a && control.source_date_field_b"
                          outlined
                          class="col"
                          v-model.number="ruleConfigObject.time_shift_from"
                          type="number"
                          label="Time shift from"
                          @update:model-value="ReconciliationTimeShiftFromChanged">
                          <template v-slot:prepend>
                            <q-icon name="far fa-clock" @click.stop.prevent />
                          </template>
                          <q-tooltip anchor="top right" self="bottom right" :offset="[0, 5]">
                            Lower timeshift tolerance value in seconds <br />
                            (if A minus B is between this value and "Time tolerance from" - output as mismatch)
                          </q-tooltip>
                        </q-input>

                        <q-input
                          v-if="control.source_date_field_a && control.source_date_field_b"
                          outlined
                          class="col"
                          v-model.number="ruleConfigObject.time_shift_to"
                          type="number"
                          label="Time shift to"
                          @update:model-value="ReconciliationTimeShiftToChanged">
                          <template v-slot:prepend>
                            <q-icon name="far fa-clock" @click.stop.prevent />
                          </template>
                          <q-tooltip anchor="top right" self="bottom right" :offset="[0, 5]">
                            Upper timeshift tolerance value in seconds <br />
                            (if A minus B is between "Time tolerance to" and this value - output as mismatch)
                          </q-tooltip>
                        </q-input>
                      </div>
                    </q-card-section>
                  </q-card>

                  <reconciliation-match-criteria-box
                    class="col"
                    v-model="ruleConfigObject"
                    :datasource-a-columns="datasourceAColumns"
                    :datasource-b-columns="datasourceBColumns">
                  </reconciliation-match-criteria-box>

                  <reconciliation-mis-match-criteria-box
                    class="col"
                    v-model="ruleConfigObject"
                    :datasource-a-columns="datasourceANumColumns"
                    :datasource-b-columns="datasourceBNumColumns">
                  </reconciliation-mis-match-criteria-box>

                  <reconciliation-discrepancy-checkboxes class="col" :control="control" v-model="ruleConfigObject">
                  </reconciliation-discrepancy-checkboxes>
                  <br />
                </div>
              </div>
            </q-tab-panel>

            <q-tab-panel name="sql">
              <div class="q-ma-lg q-gutter-y-lg">
                <div class="row q-gutter-md">
                  <div class="col">
                    <code-box
                      label="Preparation SQL"
                      :template-vars="true"
                      :tables="ruleDatasourceTables"
                      v-model="control.preparation_sql"
                      :examples="codeExamples.preparation"
                      :check="checker('preparation')">
                    </code-box>
                    <q-tooltip anchor="top left" self="bottom left" :offset="[-120, -20]">
                      Preparation SQL is executed before the control is started. It can be used to prepare the data for the control. See the enclosed examples.
                    </q-tooltip>
                  </div>
                </div>

                <div class="row q-gutter-md">
                  <div class="col">
                    <code-box
                      label="Prerequisite SQL"
                      :template-vars="true"
                      :tables="ruleDatasourceTables"
                      v-model="control.prerequisite_sql"
                      :examples="codeExamples.prerequisite"
                      :check="checker('prerequisite')">
                    </code-box>
                    <q-tooltip anchor="top left" self="bottom left" :offset="[-120, -20]">
                      Prerequisite SQL is executed before the control is started. If the number returned is 0 the control will be terminated. See the enclosed
                      positive and negative examples.
                    </q-tooltip>
                  </div>
                </div>

                <div class="row q-gutter-md">
                  <div class="col">
                    <code-box
                      label="Completion SQL"
                      :template-vars="true"
                      :tables="ruleDatasourceTables"
                      v-model="control.completion_sql"
                      :examples="codeExamples.completion"
                      :check="checker('completion')">
                    </code-box>
                    <q-tooltip anchor="top left" self="bottom left" :offset="[-120, -20]">
                      Completion SQL is executed after the control is finished. It can be used to clean-up data, log results or execute chain of controls. See
                      the enclosed examples.
                    </q-tooltip>
                  </div>
                </div>
              </div>
            </q-tab-panel>

            <q-tab-panel name="case">
              <div class="q-ma-lg">
                <div class="column q-gutter-y-xl">
                  <div class="col">
                    <case-config-box class="col" v-model="caseConfigObject"> </case-config-box>
                  </div>
                  <div class="col">
                    <code-box
                      label="Case mapping"
                      v-model="control.case_definition"
                      :columns="datasourceColumns"
                      :examples="codeExamples.case_definition"
                      :check="checker('case_definition', 'source_name')">
                    </code-box>
                    <q-tooltip anchor="top left" self="bottom left" :offset="[0, 5]">
                      Use simple SQL case structure to define which discrepancies will be mapped to which Case IDs defined above. See the enclosed example.
                    </q-tooltip>
                  </div>
                </div>
              </div>
            </q-tab-panel>

            <q-tab-panel name="scheduler">
              <div class="q-ma-lg q-gutter-y-md">
                <div class="row q-gutter-md">
                  <q-select
                    class="col-2"
                    outlined
                    emit-value
                    map-options
                    v-model="control.status"
                    :options="[
                      { label: 'Active', value: 'Y' },
                      { label: 'Inactive', value: 'N' },
                    ]"
                    label="Scheduler status" />

                  <schedule-edit-box ref="scheduleBox" class="col" v-model="scheduleObject">
                    <div class="row no-wrap items-start q-gutter-x-sm">
                      <q-icon name="fas fa-comment-alt" color="grey-6" size="14px" />
                      <schedule-description
                        :schedule-config="scheduleConfigText"
                        :trigger-name="scheduleTriggerName"
                        :period-back="control.period_back"
                        :period-number="control.period_number"
                        :period-type="control.period_type"
                        color="teal-7" />
                    </div>
                  </schedule-edit-box>
                </div>
                <div class="row q-gutter-md">
                  <q-input outlined class="col-2" v-model.number="control.period_back" type="number" label="Periods back">
                    <template v-slot:prepend>
                      <q-icon name="fas fa-history" @click.stop.prevent />
                    </template>
                  </q-input>

                  <q-input class="col-2" v-model.number="control.period_number" type="number" outlined label="Number of periods">
                    <template v-slot:prepend>
                      <q-icon name="fas fa-calendar-day" @click.stop.prevent />
                    </template>
                  </q-input>

                  <q-select
                    class="col-2"
                    outlined
                    emit-value
                    map-options
                    v-model="control.period_type"
                    :options="periodTypeOptions"
                    label="Period type" />
                </div>
                <!-- A scheduled cascade gets the fire time of its trigger, not its window (Control._cascade_dates). -->
                <div v-if="scheduleType === 'C'" class="text-caption text-grey-8">
                  <q-icon name="fas fa-info-circle" class="q-mr-xs" />Counted back from the fire time of
                  {{ scheduleTriggerName ? `${scheduleTriggerName}, the control this one follows` : "the control this one follows" }}. A manual run of it passes its own
                  dates instead.
                </div>

                <div v-if="scheduleType !== 'C'" class="row q-gutter-md">
                  <iteration-config-box class="col" v-model="iterationConfigObject" :pb="control.period_back"> </iteration-config-box>
                </div>
              </div>
            </q-tab-panel>
            <q-tab-panel name="kpi">
              <div class="q-ma-lg q-gutter-y-md">
                <q-banner v-if="kpiRenameShown" dense rounded class="bg-blue-1 text-blue-10">
                  <template v-slot:avatar><q-icon name="fas fa-info-circle" color="blue-7" size="sm" /></template>
                  The KPI statements follow the control name: {{ kpiRenamePrefix }}{{ kpiRenameFrom }} → {{ kpiRenamePrefix }}{{ kpiTableName }} in
                  {{ kpiRenameList }}.
                  <template v-slot:action>
                    <q-btn flat dense no-caps color="primary" label="Undo" @click="undoKpiRename">
                      <q-tooltip>Point the statements back to {{ kpiRenameFrom }} and stop following the name</q-tooltip>
                    </q-btn>
                  </template>
                </q-banner>
                <div class="row q-gutter-md">
                  <kpi-config-box
                    class="col"
                    v-model="kpiConfigObject"
                    :control-name="control.control_name"
                    :control-type="control.control_type"
                    :calculable="schemaEnabled"
                    :runs-control-name="savedControlName"
                    :initial-process-id="routeProcessId">
                  </kpi-config-box>
                </div>
              </div>
            </q-tab-panel>
            <q-tab-panel v-if="emailEnabled" name="email">
              <div class="q-ma-lg q-gutter-y-md">
                <email-config-box
                  v-model="ruleConfigObject.email"
                  :control-name="control.control_name"
                  :control-type="control.control_type"
                  :rule-config="control.control_type === 'REC' ? ruleConfigObject : null"
                  :source-columns="emailSourceColumns"
                  :saved="Boolean(control.control_id) && !dirty"
                  :reveal="emailReveal">
                </email-config-box>
              </div>
            </q-tab-panel>
            <q-tab-panel name="log" class="editor-panel-open">
              <div class="q-mt-md">
                <!-- One row: the periods loaded (the latest first, older ones as the table scrolls), the totals of the runs
                     loaded and the sort chip on the left, the status chips on the right. -->
                <run-summary v-if="logsLoaded" :runs="controlLogs" inline class="q-mb-md">
                  <template v-if="logPeriodsText" #lead>
                    <span :title="logPeriodsTitle">{{ logPeriodsText }}</span>
                  </template>
                  <filter-chips :filters="[]" :sort="logSortChip" class="inline q-ml-sm" style="vertical-align: middle" />
                </run-summary>
                <!-- The Results table, without its filters, side B for ANL and REP and Edit control, plus a column per KPI
                     stored for the runs; Type and Control (the same on every row) are dropped when the width is
                     needed. -->
                <div ref="logTable" class="column no-wrap" :style="{ maxHeight: logTableHeight + 'px' }">
                  <run-table
                    :runs="controlLogs"
                    :sort="logSort"
                    :columns="{ type: true, name: 'optional', b: ['REC', 'CMP'].includes(control.control_type) }"
                    :kpi-columns="kpiAvailable ? logKpiTypes : []"
                    expand-key="rapo_runs_expand_runlog"
                    :focus-run="logFocus"
                    selectable
                    :edit-link="false"
                    :run-disabled="dirty ? 'Apply your changes first: a run uses the saved configuration' : null"
                    :refresh="refreshLogs"
                    :loading="!logsLoaded"
                    :more="logPeriods.more && logSortsByPeriod"
                    :loading-more="logPeriods.loadingMore"
                    loading-more-text="Loading older periods…"
                    @load-more="loadOlderLogs()"
                    :has-kpis="() => kpiConfigObject.length > 0"
                    @calculate-kpis="(run) => openKpiCalculate(run.process_id)" />
                </div>
              </div>
            </q-tab-panel>
          </q-tab-panels>

          <div v-if="readOnly" class="editor-actions row items-center q-gutter-sm q-px-lg q-py-sm">
            <q-btn label="Close" color="primary" flat @click="$router.push({ name: 'controls' })" />
          </div>
          <div v-else class="editor-actions row items-center q-gutter-sm q-px-lg q-py-sm">
            <q-btn label="Save" color="primary" :loading="saving" @click="persist('close')">
              <q-tooltip anchor="top left" self="bottom left" :offset="[0, 5]">Save and return to the controls</q-tooltip>
            </q-btn>
            <q-btn label="Apply" color="primary" outline :disable="!dirty || saving" @click="persist('stay')">
              <q-tooltip anchor="top left" self="bottom left" :offset="[0, 5]">Save and keep editing (Ctrl+S)</q-tooltip>
            </q-btn>
            <q-btn label="Cancel" type="reset" color="primary" flat />
            <q-space />
            <div v-if="schemaCheckPending" class="text-grey-7 text-weight-medium row items-center no-wrap">
              <q-spinner size="12px" class="q-mr-sm" />
              Checking schema…
              <q-tooltip anchor="top middle" self="bottom middle" :offset="[0, 5]">
                Comparing the result tables with the schema the configuration would create. Large or complex views take a while.
              </q-tooltip>
            </div>
            <div
              v-else-if="schemaNotice"
              class="schema-notice text-weight-medium row items-center no-wrap cursor-pointer"
              :class="schemaNotice.class"
              v-keyboard:button
              @click="$refs.schemaDialog.open()">
              <q-icon :name="schemaNotice.icon" size="12px" class="q-mr-sm" />
              {{ schemaNotice.label }}
              <q-tooltip anchor="top middle" self="bottom middle" :offset="[0, 5]">{{ schemaNotice.tooltip }}</q-tooltip>
            </div>
            <div
              v-if="dirty"
              class="text-orange-9 text-weight-medium row items-center no-wrap"
              :class="{ 'cursor-pointer': savedControlJson !== null }"
              v-keyboard:button="savedControlJson !== null"
              @click="savedControlJson !== null && $refs.controlDiffDialog.open()">
              <q-icon name="fas fa-circle" size="8px" class="q-mr-sm" />
              Unsaved changes
              <q-tooltip v-if="savedControlJson !== null" anchor="top middle" self="bottom middle" :offset="[0, 5]">
                Show what Apply will change
              </q-tooltip>
            </div>
            <template v-if="schemaEnabled && !schemaCheck?.rebuilt_each_run">
              <q-btn v-if="schemaSummary.safe" label="Update schema" color="primary" outline :disable="saving || schemaBusy" @click="applySchema('update')">
                <q-tooltip anchor="top middle" self="bottom middle" :offset="[0, 5]">Add and widen columns of the result tables, keeping their data</q-tooltip>
              </q-btn>
              <!-- Only while the tables differ from the configuration; otherwise the Controls list's row menu has it. -->
              <q-btn
                v-if="schemaNotice"
                label="Recreate schema"
                color="negative"
                :flat="!schemaRecreateSuggested"
                :unelevated="schemaRecreateSuggested"
                :disable="saving || schemaBusy"
                @click="$refs.schemaDialog.open()">
                <q-tooltip anchor="top middle" self="bottom middle" :offset="[0, 5]">
                  Drop the result tables and create them anew: past results are deleted. Shows the tables first.
                </q-tooltip>
              </q-btn>
            </template>
          </div>
        </q-form>
      </q-card>
    </div>

    <view-edit-dialog ref="viewDialog" :control-name="savedControlName" @compiled="viewCompiled" />
    <schema-diff-dialog
      ref="schemaDialog"
      :check="schemaCheck"
      :dirty="dirty"
      :busy="saving || schemaBusy"
      :exact-rows="schemaExactRows"
      :counting-rows="schemaCountingRows"
      @count="countSchemaRows"
      @drop="dropOrphan"
      @update="applySchema('update')"
      @recreate="(tables) => applySchema('recreate', tables)" />
    <control-diff-dialog
      ref="controlDiffDialog"
      :diff="unsavedChanges"
      :busy="saving"
      @apply="persist('stay')"
      @undo="undoChange"
      @discard="discardAll" />
    <control-versions-dialog
      ref="versionsDialog"
      :current="savedVersionRow"
      :versions="pastVersions"
      :loaded-id="controlVersion && controlVersion.version_id"
      @load="loadVersion"
      @changed="refreshVersions" />
    <kpi-calculate-dialog ref="kpiCalculate" />
  </q-page>
</template>

<script>
import { mapActions, mapGetters, mapState } from "vuex";
import { api, notifyError } from "../api";
import { CONTROL_ENGINE_OPTIONS, CONTROL_TYPE_OPTIONS, PERIOD_TYPE_OPTIONS, YES_NO_OPTIONS, controlType } from "../constants";
import { liveRefetch } from "../socket";
import CodeBox from "./CodeBox.vue";
import EditorSkeleton from "./EditorSkeleton.vue";
import RunSummary from "./RunSummary.vue";
import RunTable from "./RunTable.vue";
import SchemaDiffDialog from "./SchemaDiffDialog.vue";
import ControlDiffDialog from "./ControlDiffDialog.vue";
import ControlVersionsDialog from "./ControlVersionsDialog.vue";
import RunControlDialog from "./RunControlDialog.vue";
import ScheduleEditBox from "./ScheduleEditBox.vue";
import ScheduleDescription from "./ScheduleDescription.vue";
import ReconciliationDiscrepancyCheckboxes from "./ReconciliationDiscrepancyCheckboxes.vue";
import ReconciliationMatchCriteriaBox from "./ReconciliationMatchCriteriaBox.vue";
import ReconciliationMisMatchCriteriaBox from "./ReconciliationMisMatchCriteriaBox.vue";
import CaseConfigBox from "./CaseConfigBox.vue";
import IterationConfigBox from "./IterationConfigBox.vue";
import KpiConfigBox from "./KpiConfigBox.vue";
import KpiCalculateDialog from "./KpiCalculateDialog.vue";
import ViewEditDialog from "./ViewEditDialog.vue";
import { renameKpiTables } from "../utils/kpi";
import EmailConfigBox from "./EmailConfigBox.vue";
import ComparisonCriteriaBox from "./ComparisonCriteriaBox.vue";
import ComparisonOutputTableBox from "./ComparisonOutputTableBox.vue";
import { examplesFor } from "../utils/codeExamples";
import { diffControl, diffKpis, revertControlPath, revertKpiPath } from "../utils/controlDiff";
import editorGuard from "../mixins/editorGuard";
import { escapeHtml, toDateTimeString } from "../utils/format";
import FilterChips from "./FilterChips.vue";
import { KPI_SORT_PREFIX, RUN_SORT_LABELS } from "../utils/runs";
import { sortChip } from "../utils/sort";
import { describeOrphan, describeTable, summarizeSchema } from "../utils/schema";
import { defaultSchedule, parseSchedule, scheduleType, serializeSchedule } from "../utils/schedule";
import { allUpstreams, nameIndex, upstreamsOf } from "../utils/chain";
import { controlGroups, controlSystems, filterOptions, normalizeOption } from "../utils/controlGroups";
import { EMAIL_CONTROL_TYPES, completeEmailConfig, defaultEmailConfig, emailConfigProblem } from "../utils/email";

// The label of a version in the Version select and the Manage versions dialog.
function versionLabel(version) {
  return "v." + toDateTimeString(version.updated_date ? version.updated_date : version.created_date);
}

// The Run log's sort, kept for the browser session like a list page's (mixins/persistFilters).
const LOG_SORT_KEY = "rapo_filters_control_runlog";

function readLogSort() {
  try {
    const saved = JSON.parse(sessionStorage.getItem(LOG_SORT_KEY) || "null");
    // end_date: the End column of an earlier Run log; the type and name columns are not in it.
    if (saved && typeof saved.key === "string" && !["end_date", "control_type", "control_name"].includes(saved.key) && ["asc", "desc"].includes(saved.dir)) {
      return saved;
    }
  } catch (error) {
    // The default then.
  }
  // The periods read, newest first.
  return { ...LOG_DEFAULT_SORT };
}

// The Run log's default order, the one it pages in: the latest period first.
const LOG_DEFAULT_SORT = { key: "date_from", dir: "desc" };
// Periods per page of the Run log (get-control-runs), the least it shows.
const LOG_PERIODS = 14;

// The KPI types of the Run log's pages together, by priority, then code (as get-control-runs orders them).
function mergeKpiTypes(types, more) {
  const known = new Set(types.map((type) => type.kpi_type));
  const merged = [...types, ...more.filter((type) => !known.has(type.kpi_type))];
  const priority = (type) => (type.kpi_priority == null ? Infinity : type.kpi_priority);
  return merged.sort((a, b) => priority(a) - priority(b) || a.kpi_type.localeCompare(b.kpi_type));
}

export default {
  mixins: [editorGuard],
  components: {
    CodeBox,
    EditorSkeleton,
    FilterChips,
    RunSummary,
    RunTable,
    RunControlDialog,
    SchemaDiffDialog,
    ControlDiffDialog,
    ControlVersionsDialog,
    ScheduleEditBox,
    ScheduleDescription,
    ReconciliationDiscrepancyCheckboxes,
    ReconciliationMatchCriteriaBox,
    ReconciliationMisMatchCriteriaBox,
    CaseConfigBox,
    IterationConfigBox,
    KpiConfigBox,
    KpiCalculateDialog,
    ViewEditDialog,
    EmailConfigBox,
    ComparisonCriteriaBox,
    ComparisonOutputTableBox,
  },
  props: {
    controlId: {
      type: String,
      default: "new",
    },
  },
  // The boxes of a read-only editor (CodeBox) are read only too.
  provide() {
    return { editorReadonly: () => this.readOnly };
  },
  data() {
    return {
      // The email problem the Email tab scrolls to after a refused save ({ file, sheet } of emailConfigProblem).
      emailReveal: null,
      // The Control group field's options, narrowed to the typed text.
      controlGroupOptions: [],
      // The System fields' options, narrowed to the typed text.
      systemOptions: [],
      // The window variables are still completed in the datasource filters, but get no chip: the date column
      // already limits the fetch to the window.
      filterHiddenChips: ["control_date_from", "control_date_to"],
      tab: "main",
      // False until the control (or a new one) is set up, so the editor never shows an empty form first.
      ready: false,
      control: {},
      controlVersions: [],
      controlVersion: null,
      datasourceColumns: null,
      datasourceDateColumns: null,
      datasourceAColumns: null,
      datasourceADateColumns: null,
      datasourceANumColumns: null,
      datasourceBColumns: null,
      datasourceBDateColumns: null,
      datasourceBNumColumns: null,
      datasourceList: null,
      datasourceListOptions: null,
      // {NAME: "TABLE" | "VIEW"} of the datasource list; a view gets the Edit view SQL button.
      datasourceTypes: {},
      withDeletionDrop: "N",
      scheduleObject: defaultSchedule(),
      ruleConfigObject: {},
      cmpOutputTable: [],
      ruleErrorObject: [],
      caseConfigObject: [],
      iterationConfigObject: [],
      kpiConfigObject: [],
      // The runs of the latest periods loaded (get-control-runs), shown by the Run log's RunTable.
      controlLogs: [],
      // The Run log's paging by periods: how many the control has, whether older ones are left, the oldest loaded
      // ({date_from, date_to}: a refresh reloads down to it, the next page starts after it) and whether a page is
      // being loaded. `logThrough`: the period the first load reaches down to (a ?run= link), or null.
      logPeriods: { total: 0, more: false, oldest: null, loadingMore: false },
      logThrough: null,
      // The run the Run log was opened on (?run=, from Results), shown with its period's versions; null otherwise.
      logFocus: null,
      // The KPI types stored for the runs of the Run log (get-control-runs' kpi_types), a column each.
      logKpiTypes: [],
      logsLoaded: false,
      // The Run log's sort, kept for the browser session (LOG_SORT_KEY), and the table's height down to the
      // Save/Apply bar.
      logSort: readLogSort(),
      logTableHeight: 600,
      versionChanges: [],
      saving: false,
      // Set when a stored JSON column of the loaded row could not be read: the form then holds defaults, so Save is refused.
      configError: null,
      // The saved state as JSON (buildControlPayload / kpiConfigObject), compared with the form for dirty.
      // null control: never saved (a clone); null KPIs: not loaded yet, not compared.
      savedControlJson: null,
      savedKpiJson: null,
      // True while a control is being loaded, so the datasource watchers don't reset its saved fields.
      initializing: false,
      // The control name the KPI statements' result table names refer to (the loaded one, the source of a clone),
